source.jsLib:
var API='https://yeguodj.com/api.php';
var BASE={bundleId:'com.pwa.mater',version:'1.3.2',oauth_type:'web',language:'zh',via:'pwa',oauth_id:'7d05538c4b8a5e74e82f93c0dab0163c',token:'',trace_id:'7d05538c4b8a5e74e82f93c0dab0163c'};
var AESKEY='2acf7e91e9864673',AESIV='1c29882d3ddfcfd6';
function ygBody(m){
  var b=[];
  for(var k in m){if(m[k]!==null&&m[k]!==undefined){b.push(k+'='+encodeURIComponent(String(m[k])));}}
  return b.join('&');
}
function ygUrlCfg(path, body){
  return API+path+',{"method":"POST","body":"'+body+'","headers":{"Content-Type":"application/x-www-form-urlencoded"}}';
}
function ygMerge(extra){
  var m={};
  for(var k in BASE){m[k]=BASE[k];}
  for(var k2 in extra){m[k2]=extra[k2];}
  return ygBody(m);
}
function ygExploreUrl(page, filter){
  var m={};
  for(var k in BASE){m[k]=BASE[k];}
  m.page=String(page||1);
  for(var k2 in filter){m[k2]=String(filter[k2]);}
  return ygUrlCfg('/theater/exploreList',ygBody(m));
}
function ygPlayUrlCfg(eid,vid){
  return ygUrlCfg('/playlet/play',ygMerge({episode_id:String(eid),video_id:String(vid)}));
}
function ygDecryptData(dataB64){
  var k=CryptoJS.enc.Utf8.parse(AESKEY);
  var iv=CryptoJS.enc.Utf8.parse(AESIV);
  var d=CryptoJS.AES.decrypt({ciphertext:CryptoJS.enc.Base64.parse(String(dataB64))},k,{iv:iv,padding:CryptoJS.pad.Pkcs7});
  return d.toString(CryptoJS.enc.Utf8);
}
function ygRespData(respText){
  var resp=JSON.parse(String(respText));
  if(!resp.data){return null;}
  var plain=ygDecryptData(resp.data);
  var j=JSON.parse(plain);
  return j.data||j;
}

