        ['马甲',18],['闪婚',37],['现代',35],['穿书',52],['一见钟情',58],
        ['年代',1],['女强',12],['宫斗宅斗',31],['萌宝',13],['奇幻脑洞',66],
        ['青梅竹马',49],['先婚后爱',11],['穿越',4],['亲情',29],['重生',7],
        ['玄学',46],['大女主',40],['暗恋成真',53],['追妻',28],['甜宠',19],
        ['奇幻',14],['日久生情',25],['打脸虐渣',21],['欢喜冤家',44]
    ];

    var actionJs = "var s={ch:infoMap['频道']||'男频',ct:infoMap['分类']||'类型',rk:infoMap['排行']||'排行榜'}; source.setVariable(JSON.stringify(s)); java.refreshExplore();";

    var cache = {};
    try { cache = JSON.parse(source.getVariable()); } catch(e){}
    if (!cache.dev_id) {
        cache.dev_id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c){
            var r = Math.random()*16|0, v = c=='x'?r:(r&0x3|0x8);
            return v.toString(16);
        });
        source.setVariable(JSON.stringify(cache));
    }
    var devId = cache.dev_id;
    var authH = '{"headers":{"publicId":"' + devId + '","deviceId":"' + devId + '","m2":"' + devId + '"}}';

    var ui = [];
    ui.push({title:'频道', type:'select', chars:['男频','女频'], default:state.ch, action:actionJs, style:{layout_flexBasisPercent:1}});
    ui.push({title:'分类', type:'select', chars:['类型','剧情'], default:state.ct, action:actionJs, style:{layout_flexBasisPercent:1}});
    ui.push({title:'排行', type:'select', chars:['排行榜','推荐','最新'], default:state.rk, action:actionJs, style:{layout_flexBasisPercent:1}});
    ui.push({title:'关键字', type:'text', default:'', style:{layout_flexBasisPercent:1}});
    ui.push({title:'搜短剧', type:'button', action:"var k=infoMap['关键字']; if(!k){ java.toast('请输入关键字'); } else { java.searchBook(k, source); }", style:{layout_flexBasisPercent:1}});

    // 排行链接（根据rk状态高亮对应项）
    ui.push({title:'排行榜', url:'https://ts3.txs12.com/playlet/rank', style:{layout_flexGrow:1, layout_flexBasisPercent:0.33}});
    ui.push({title:'推荐', url:'https://ts3.txs12.com/playlet/list-video, ' + authH, style:{layout_flexGrow:1, layout_flexBasisPercent:0.33}});
    ui.push({title:'最新', url:'https://ts3.txs12.com/playlet/video/new, ' + authH, style:{layout_flexGrow:1, layout_flexBasisPercent:0.33}});

    if (state.ct === '类型') {
        // 分类名称 → 按钮触发搜索
        var cates = (state.ch === '男频') ? maleCates : femaleCates;
        for (var i = 0; i < cates.length; i++) {
            var cat = cates[i];
            ui.push({title:cat, type:'button', action:"java.searchBook('" + cat + "', source)", style:{layout_flexGrow:1, layout_flexBasisPercent:0.33}});
        }
    } else {
        // 剧情标签 → 跳转标签页
        var tags = (state.ch === '男频') ? maleTags : femaleTags;
        for (var i = 0; i < tags.length; i++) {
            var t = tags[i];
            ui.push({title:t[0], url:'https://ts3.txs12.com/playlet/tags/' + t[1], style:{layout_flexGrow:1, layout_flexBasisPercent:0.25}});
        }
    }

    return JSON.stringify(ui);
})()

